using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalTests
{
    private readonly CalculatePayableTotal _useCase = new(new LoyaltyDiscountPolicy());

    [Theory]
    [InlineData(10_000, 9_500)]
    [InlineData(20_000, 19_000)]
    [InlineData(5_000, 4_750)]
    public void Gold_member_gets_five_percent_off_the_subtotal(int subtotalCents, int expectedPayableTotalCents)
    {
        var actualPayableTotalCents = _useCase.For(subtotalCents, LoyaltyTier.Gold);

        Assert.Equal(expectedPayableTotalCents, actualPayableTotalCents);
    }

    [Fact]
    public void Gold_member_with_an_empty_basket_pays_nothing()
    {
        var actualPayableTotalCents = _useCase.For(0, LoyaltyTier.Gold);

        Assert.Equal(0, actualPayableTotalCents);
    }
}
EOF
